{
  "technical_and_design_decisions": [
    "Treat the increment as work on the existing Spring XD codebase and preserve its established module, build, testing, and documentation conventions.",
    "Implement Spark Streaming processors in both Java and Scala, exposing them through the existing XD data-processing abstractions rather than introducing a separate execution model.",
    "Use the project's existing build system and dependency-management approach for Windows compatibility, applying only platform-specific fixes where required.",
    "Provision a reproducible Windows EC2 environment for acceptance testing and create a CI prototype if the existing CI system supports Windows workers.",
    "Handle Kafka and SHDP upgrades as compatibility and dependency-integration changes, including backporting existing Kafka XD changes before adopting the target Kafka SI GA release.",
    "Update the generated or maintained reference-guide source and regenerate the PDF rather than editing only the binary PDF artifact.",
    "Prioritize automated unit, integration, acceptance, and platform validation for all behavior-changing work."
  ],
  "assumptions": [
    "The existing XD repository, build environment, test infrastructure, and access to required source repositories are available.",
    "The exact 1.0, 1.1, Kafka SI GA, and SHDP GA source versions are known to the developer, although they are not specified here.",
    "The migration from 1.0 to 1.1 requires compatibility guidance and targeted code changes for representative custom modules, not migration of an entire customer installation.",
    "The Pig deliverable is one documented, runnable sample job or script with the required XD configuration and basic verification.",
    "Windows build support covers the main developer build and relevant tests on a supported Windows version; unrelated third-party platform defects are out of scope.",
    "The Windows acceptance environment uses one EC2 image and the existing acceptance-test suite. CI work is limited to a working proof of concept rather than production-grade fleet management.",
    "Spark Streaming processors are demonstration-quality but production-structured components, including Java and Scala implementations, configuration, tests, and documentation.",
    "The Spark Streaming work can use the versions already compatible with the repository; a broader Spark or framework upgrade is excluded.",
    "The copyright change affects one reference-guide PDF and its source, with no legal review or broad documentation redesign required.",
    "Kafka and SHDP upgrades may require normal API, configuration, dependency, and test adjustments, but do not require redesigning the messaging or data-processing architecture.",
    "Effort includes implementation, local debugging, documentation, and developer testing, but excludes elapsed waiting time, external approvals, and work by other people.",
    "All estimates are most likely individual developer work-hours."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Increment planning and repository baseline",
      "activity_description": "Review the existing XD architecture, build profiles, module conventions, dependency versions, test suites, release process, and the eight requested outcomes; establish a local baseline build and identify likely integration points.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A2",
      "activity_name": "1.0 to 1.1 migration and custom-module portability",
      "activity_description": "Analyze breaking changes, update migration guidance, port representative custom modules or compatibility examples, adjust APIs and configuration as needed, and add regression coverage demonstrating operationalization of existing data pipelines.",
      "most_likely_effort": 72
    },
    {
      "activity_id": "A3",
      "activity_name": "Pig script and job sample",
      "activity_description": "Create a runnable Pig script or job example, add the XD integration configuration and supporting metadata, verify execution against the expected runtime, and document the sample in the appropriate reference material.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A4",
      "activity_name": "Windows developer build support",
      "activity_description": "Run the project build on Windows, identify and fix path, shell, filesystem, dependency, scripting, or test assumptions, update build instructions, and validate a clean developer build.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "A5",
      "activity_name": "Windows EC2 acceptance-test environment and CI prototype",
      "activity_description": "Define and provision a Windows EC2 image, install project prerequisites, configure the acceptance-test environment, execute and troubleshoot the acceptance suite, capture setup documentation, and prototype a Windows CI build where feasible.",
      "most_likely_effort": 72
    },
    {
      "activity_id": "A6",
      "activity_name": "Spark Streaming Java processors",
      "activity_description": "Design and implement the Spark Streaming data processors using Java and Java lambda-based processing where appropriate, integrate them with XD configuration and lifecycle conventions, and add unit and integration tests.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "A7",
      "activity_name": "Spark Streaming Scala processors",
      "activity_description": "Implement the corresponding Spark Streaming processor demonstrations in Scala, integrate them with the existing module model, validate packaging and runtime behavior, and add Scala-specific tests and usage documentation.",
      "most_likely_effort": 48
    },
    {
      "activity_id": "A8",
      "activity_name": "Spark Streaming examples and end-to-end validation",
      "activity_description": "Create representative configuration and usage examples for both Spark Streaming implementations, verify end-to-end pipeline execution, troubleshoot interoperability issues, and document supported assumptions and limitations.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A9",
      "activity_name": "Reference-guide copyright update",
      "activity_description": "Change the reference-guide copyright year from 2014 to 2015 in the source, regenerate the PDF, inspect the resulting artifact, and verify that no stale year remains in the relevant guide.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A10",
      "activity_name": "Kafka SI GA upgrade and XD backport",
      "activity_description": "Backport the existing Kafka XD changes to the Spring Integration Kafka version, update dependencies to the target GA release, resolve API and configuration incompatibilities, update tests, and validate producer, consumer, and pipeline behavior.",
      "most_likely_effort": 96
    },
    {
      "activity_id": "A11",
      "activity_name": "SHDP GA upgrade",
      "activity_description": "Update SHDP dependencies and integration points to the GA release, resolve compile-time and runtime compatibility issues, update affected configuration and tests, and validate the relevant Hadoop-related XD functionality.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "A12",
      "activity_name": "Cross-cutting regression, packaging, documentation, and release verification",
      "activity_description": "Run the full available test matrix, perform integration and packaging checks, resolve cross-feature regressions, update changelog or release notes, review build reproducibility, and prepare the increment for delivery.",
      "most_likely_effort": 40
    }
  ],
  "reported_total": {
    "most_likely_effort": 556
  }
}

